        $filters=[['key'=>'from','label'=>'From date','type'=>'date'],['key'=>'to','label'=>'To date','type'=>'date'],['key'=>'status','label'=>'Status','type'=>'text']];
        $specific=['bookings'=>['date_type','branch','customer','agent','salesperson','product'],'passengers'=>['branch','customer','passenger','pax_type','gender','nationality','product'],'hotels'=>['date_type','branch','customer','vendor','city','hotel'],'visas'=>['date_type','branch','customer','passenger','visa_type','saudi_company','pakistani_iata','vendor'],'transport'=>['date','branch','customer','vendor','route','vehicle_type'],'group-umrah'=>['date_type','branch','customer','package','makkah_hotel','madinah_hotel','saudi_company','pakistani_iata','agent','salesperson'],'air'=>['date_type','branch','customer','vendor','airline','origin','destination','sector','ticket_status','pnr','ticket_no','issue_date','agent','salesperson']][$key]??['branch','customer'];
